import React, { useState, useEffect } from "react";
import "./taskflow.css";

function Taskflow() {

    const API_URL = "http://localhost:8000/api/tasks";

    const [search, setSearch] = useState("");
    const [newTask, setNewTask] = useState("");
    const [selectedId, setSelectedId] = useState(null);
    const [tasks, setTasks] = useState([]);

    // 1. Get all tasks when page loads
    useEffect(() => {

        async function getTasks() {
            try {
                const response = await fetch(API_URL);

                const result = await response.json();

                if (!response.ok) {
                    throw new Error("Failed to fetch tasks");
                }

                setTasks(result.data);

            } catch (error) {
                console.error("Error fetching tasks:", error);
            }
        }

        getTasks();

    }, []);

    // 2. Add new task (POST)
    async function addTask() {

        if (newTask.trim() === "") return;

        try {
            const response = await fetch(API_URL, {
                method: "POST",
                headers: {
                    "Content-Type": "application/json"
                },
                body: JSON.stringify({
                    title: newTask
                })
            });

            const result = await response.json();

            if (!response.ok) {
                throw new Error(result.error.message);
            }

            setTasks([...tasks, result]);

            setNewTask("");

        } catch (error) {
            console.error("Error adding task:", error);
        }
    }

    // 3. Select task
    function selectTask(id) {

        if (selectedId === id) {
            setSelectedId(null);
        } else {
            setSelectedId(id);
        }
    }

    // 4. Mark task as completed or pending (PATCH)
    async function toggleCompleted(id) {

        const task = tasks.find((t) => t.id === id);

        try {
            const response = await fetch(`${API_URL}/${id}`, {
                method: "PATCH",
                headers: {
                    "Content-Type": "application/json"
                },
                body: JSON.stringify({
                    completed: !task.completed
                })
            });

            const updatedTask = await response.json();

            if (!response.ok) {
                throw new Error(updatedTask.error.message);
            }

            setTasks(tasks.map((t) =>
                t.id === id ? updatedTask : t
            ));

        } catch (error) {
            console.error("Error updating task:", error);
        }
    }

    // 5. Edit task title (PATCH)
    async function editTask(id, oldTitle) {

        const title = prompt("Edit task:", oldTitle);

        if (title === null || title.trim() === "") return;

        try {
            const response = await fetch(`${API_URL}/${id}`, {
                method: "PATCH",
                headers: {
                    "Content-Type": "application/json"
                },
                body: JSON.stringify({
                    title: title
                })
            });

            const updatedTask = await response.json();

            if (!response.ok) {
                throw new Error(updatedTask.error.message);
            }

            setTasks(tasks.map((t) =>
                t.id === id ? updatedTask : t
            ));

        } catch (error) {
            console.error("Error editing task:", error);
        }
    }

    // 6. Delete task (DELETE)
    async function deleteTask(id) {

        try {
            const response = await fetch(`${API_URL}/${id}`, {
                method: "DELETE"
            });

            if (!response.ok) {
                const result = await response.json();
                throw new Error(result.error.message);
            }

            setTasks(tasks.filter((t) => t.id !== id));

            if (selectedId === id) {
                setSelectedId(null);
            }

        } catch (error) {
            console.error("Error deleting task:", error);
        }
    }

    // 7. Search tasks
    const filteredTasks = tasks.filter((t) =>
        t.title.toLowerCase().includes(search.toLowerCase())
    );

    // Find selected task
    const selectedTask = tasks.find((t) => t.id === selectedId);

    return (
        <div>

            <header className="header">
                <h1>TaskFlow</h1>
            </header>

            <div className="card">

                <h2>List View</h2>

                <input
                    className="text-box"
                    type="text"
                    placeholder="Search tasks..."
                    value={search}
                    onChange={(e) => setSearch(e.target.value)}
                />

                <div className="add-row">

                    <input
                        className="text-box"
                        type="text"
                        placeholder="Add a new task..."
                        value={newTask}
                        onChange={(e) => setNewTask(e.target.value)}
                    />

                    <button className="add-btn" onClick={addTask}>
                        Add
                    </button>

                </div>

                {filteredTasks.map((task) => (

                    <div className="task" key={task.id}>

                        <div>

                            <input
                                type="checkbox"
                                checked={selectedId === task.id}
                                onChange={() => selectTask(task.id)}
                            />

                            <span className={task.completed ? "title done" : "title"}>
                                {task.title}
                            </span>

                        </div>

                        <div className="task-buttons">

                            <button onClick={() => editTask(task.id, task.title)}>
                                Edit
                            </button>

                            <button onClick={() => deleteTask(task.id)}>
                                Delete
                            </button>

                        </div>

                    </div>

                ))}

            </div>

            {selectedTask && (

                <div className="card">

                    <h2>Detail View</h2>

                    <p className="label">Title</p>
                    <p className="value">{selectedTask.title}</p>

                    <p className="label">Status</p>
                    <p className="value">
                        {selectedTask.completed ? "Completed" : "Pending"}
                    </p>

                    <p className="label">Created</p>
                    <p className="value">{selectedTask.createdAt}</p>

                    <div className="task-buttons">

                        <button onClick={() => toggleCompleted(selectedTask.id)}>
                            {selectedTask.completed
                                ? "Mark as Pending"
                                : "Mark as Completed"}
                        </button>

                        <button onClick={() => deleteTask(selectedTask.id)}>
                            Delete
                        </button>

                    </div>

                </div>

            )}

        </div>
    );
}

export default Taskflow;
